package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables in the unit block (common in Ansible vars files, Chef attributes)
    variable := parent.variables[_]

    # Check if variable name contains credential-related keywords
    contains_credential_keyword(variable.name)

    # Check if the value is an empty string, null, or undefined
    is_empty_password(variable.value)

    result := {
        "type": "sec_empty_pass",
        "element": variable,
        "path": parent.path,
        "description": "Empty password assigned to credential field - Passwords should not be empty. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in atomic units (common in Puppet, Chef resources)
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name contains credential-related keywords
    contains_credential_keyword(attr.name)

    # Check if the value is an empty password
    is_empty_password(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password assigned to credential field - Passwords should not be empty. (CWE-258)"
    }
}

# Helper function to check if a name contains credential-related keywords
contains_credential_keyword(name) {
    regex.match("(?i)(password|secret|token|passphrase|passwd|credential|auth|key)", name)
}

# Helper function to check if a value represents an empty password
is_empty_password(value) {
    # Empty string
    value.ir_type == "String"
    value.value == ""
} else {
    # Null value
    value.ir_type == "Null"
} else {
    # Undefined value
    value.ir_type == "Undef"
}

